# v1.3 2026-10-10  Brief 12 step 6 (PLAN 6 row 6): image memory on store DEMO with the four frozen synthetic bill
#                  PNGs and our descriptions, image search for the four frozen questions, list_images with and without
#                  bytes, and (step 0's vision check passed) one caption generated by the LLM for the TKT-48213 bill.
#                  v1.3: (Codex 28 r3) "generated" needs the text, and the transcript says whether its chunk was
#                  embedded in time; an earlier caption row WITHOUT text is never answered by a second image to the
#                  LLM (D5: one image): the caption is then reported as not attempted again.
#                  v1.2: (first run 18:51Z) add_image without a description returns at once (0.22 s) with the
#                  row stored and its description NULL; the SDK asks the LLM in the background and updates the row
#                  about 4 s later (1 LLM call, 1,032 tokens). v1.1 read the row at once and wrote "caption refused",
#                  which was wrong. Now the step waits, bounded (120 s, every 2 s), for the description and its
#                  embedded chunk, and names the outcome from what it finds: generated, refused (an LLM failure or no
#                  row) or "no caption within 120 s"; the seconds until the text appeared are reported.
#                  v1.1: (Codex 28 r1) a re-run never asks the LLM again for a caption an earlier attempt already
#                  stored: its text is kept before the leftovers are deleted and re-added as given (no LLM call);
#                  descriptions are read as whole CLOBs; a refusal's error is in the transcript too.
#                  v1.0: first version (day 1, phase 2).
"""Step 6. Run on the demo VM from ~/agentmem-poc/code with the POC venv (run_all.sh S6):
    .venv/bin/python py/60_image_memory.py
Store DEMO is opened with REQUIRE_EXISTING (never recreated: steps 1-3 and the APEX pages read it). Nothing in DEMO's
memories or links is changed; the hero statuses and links are read before and after and must be equal.
  0. The frozen inputs (data/frozen/bill_images.json and the four PNGs) must match data/frozen/FREEZE.sha256.
  1. Images of CUST_1001 already in DEMO: an id that is not one of this step's five fixed ids stops the step (nothing
     changed); this step's own ids (left by an earlier attempt) are deleted through the SDK's delete_image first.
  2. Client A (no LLM, extraction off): add_image(bytes, description=ours, image_id, user_id='CUST_1001') for the four
     images, MIME type detected by the SDK from the bytes (checked against the frozen file's image/png). 0 LLM calls.
  3. DEMO_DOCUMENT read-back (document type, MIME metadata, byte length, description); for the four questions,
     search(question, user_id='CUST_1001', record_types=['image'], max_results=10): the rank of the right image.
  4. list_images(user_id='CUST_1001', include_bytes=False); then list_images(image_id=<the bill>, user_id='CUST_1001',
     include_bytes=True): bytes equal to the file (sha256).
  5. Caption (D5: only because step 0's vision check passed, state/llm_choice.json): client B with the chosen model and
     supports_vision=True (the only such Llm in the POC), add_image(the TKT-48213 bill bytes, description omitted,
     image_id 'cust1001_img_bill_sep_llmcap'): the SDK asks the LLM for the description. At most 3 attempts (retries
     after 5 s and 20 s, PLAN 10.5); a refusal or failure is reported verbatim as "caption refused" and the step goes
     on. A caption an earlier attempt of this step already stored is not asked for again: its text is kept before
     the leftovers are deleted and re-added as a given description (reported as reused, 0 LLM calls), so one bill
     goes to the LLM once in total. The generated text is reported verbatim beside ours; then the four questions are searched again (labelled
     "after caption") and both the right image's and the captioned copy's ranks are reported. Step 3's ranks stay the
     primary result (the four described images only).
Ranks are reported as observed; nothing is retried to change one. One bill PNG goes to OCI (the approved region) for the
caption; that is the only data that leaves the database in this step.
Results: staging/s6/results/s6_image_memory.json; transcript staging/s6/transcripts/s6_transcript.md.
"""
from __future__ import annotations

import hashlib
import json
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from lib import runlog  # noqa: E402  (first: redaction before anything else)

RUN = runlog.start("s6", need_oci=True)

from lib import amconf, hero_seed, meter, stores  # noqa: E402

LITELLM = amconf.configure_litellm()

from oracleagentmemory.core import MemoryExtractionConfig, SchemaPolicy, SearchStrategy  # noqa: E402
from oracleagentmemory.observability import register_event_listeners  # noqa: E402

CODE = Path(__file__).resolve().parents[1]
FROZEN = CODE / "data" / "frozen"
SPEC = json.loads((FROZEN / "bill_images.json").read_text(encoding="utf-8"))
USER = SPEC["user_id"]
CAPTION_SOURCE_ID = "cust1001_img_bill_sep"                 # the TKT-48213 bill (section 3), D5's "one bill PNG"
CAPTION_ID = "cust1001_img_bill_sep_llmcap"
OUR_IDS = [im["image_id"] for im in SPEC["images"]]
ALL_IDS = OUR_IDS + [CAPTION_ID]
RETRY_WAITS = (5, 20)                                       # PLAN 10.5
CAPTION_WAIT_S = 120                                        # the SDK writes the generated description in the background
CAPTION_POLL_S = 2
SEARCH_KW = {"user_id": USER, "record_types": ["image"], "max_results": 10}


class StepStop(RuntimeError):
    """A precondition failed: nothing (more) is changed and the step exits 1."""


def frozen_ok() -> dict:
    """The step's inputs against the freeze manifest (PLAN 7.0 froze the images and their descriptions)."""
    want = {}
    for line in (FROZEN / "FREEZE.sha256").read_text(encoding="utf-8").splitlines():
        if line and not line.startswith("#"):
            digest, path = line.split("  ", 1)
            want[path] = digest
    out = {}
    for rel in ["data/frozen/bill_images.json"] + [f"data/frozen/{im['file']}" for im in SPEC["images"]]:
        got = hashlib.sha256((CODE / rel).read_bytes()).hexdigest()
        out[rel] = got == want.get(rel)
    return out


def hero_state(pool) -> dict:
    with pool.acquire() as c, c.cursor() as cur:
        cur.execute("select record_id, status from DEMO_MEMORY where user_id = :u order by record_id", u=USER)
        mem = [list(r) for r in cur.fetchall()]
        cur.execute("select source_memory_id, target_memory_id, relation_type from DEMO_MEMORY_LINK "
                    "order by source_memory_id, target_memory_id")
        links = [list(r) for r in cur.fetchall()]
    return {"memories": mem, "links": links}


def _text(v):
    """A CLOB read whole (python-oracledb returns a LOB object), or the value as it is."""
    return v.read() if v is not None and hasattr(v, "read") else v


def documents(pool) -> list[dict]:
    with pool.acquire() as c, c.cursor() as cur:
        cur.execute("""select record_id, document_type, user_id, status, dbms_lob.getlength(blob),
                              json_serialize(document_metadata returning varchar2(4000)), description,
                              to_char(sys_extract_utc(created_at), 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                         from DEMO_DOCUMENT where user_id = :u order by record_id""", u=USER)
        return [{"record_id": r[0], "document_type": r[1], "user_id": r[2], "status": r[3], "bytes": r[4],
                 "document_metadata": r[5], "description": _text(r[6]), "created_at_utc": r[7]}
                for r in cur.fetchall()]


def image_chunks(pool) -> list[list]:
    with pool.acquire() as c, c.cursor() as cur:
        cur.execute("select source_id, source_record_type, count(*), "
                    "sum(case when embedding is not null then 1 else 0 end) from DEMO_RECORD_CHUNKS "
                    "where source_record_type not in ('fact', 'guideline', 'memory', 'preference', 'message') "
                    "group by source_id, source_record_type order by 1")
        return [list(r) for r in cur.fetchall()]


def ranks(client, gold_of: dict, extra_id: str | None = None) -> list[dict]:
    out = []
    for q in SPEC["questions"]:
        t = time.perf_counter()
        res = client.search(q["text"], **SEARCH_KW)
        ms = round((time.perf_counter() - t) * 1000.0, 1)
        ids = [str(r.id) for r in res]
        row = {"qid": q["qid"], "question": q["text"], "gold_image_id": gold_of[q["qid"]], "returned_ids": ids,
               "distances": [getattr(r, "distance", None) for r in res],
               "rank_gold": ids.index(gold_of[q["qid"]]) + 1 if gold_of[q["qid"]] in ids else None,
               "latency_ms": ms}
        if extra_id is not None:
            row["rank_caption_copy"] = ids.index(extra_id) + 1 if extra_id in ids else None
        out.append(row)
    return out


def wait_caption(pool) -> dict:
    """Poll (read-only) until the caption row has a description and an embedded chunk, at most CAPTION_WAIT_S."""
    t0 = time.perf_counter()
    while True:
        with pool.acquire() as c, c.cursor() as cur:
            cur.execute("select description from DEMO_DOCUMENT where record_id = :i", i=CAPTION_ID)
            row = cur.fetchone()
            cur.execute("select count(*) from DEMO_RECORD_CHUNKS where source_id = :i and embedding is not null",
                        i=CAPTION_ID)
            chunks = cur.fetchone()[0]
        desc = _text(row[0]) if row else None
        waited = round(time.perf_counter() - t0, 1)
        if row is None or (desc and chunks > 0) or waited >= CAPTION_WAIT_S:
            return {"row": row is not None, "description": desc, "embedded_chunks": chunks, "seconds_waited": waited}
        time.sleep(CAPTION_POLL_S)


def caption_allowed() -> dict:
    try:
        choice = json.loads(amconf.LLM_CHOICE_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {"allowed": False, "reason": "state/llm_choice.json unreadable"}
    ok = choice.get("vision_check_passed") is True
    return {"allowed": ok, "model": choice.get("model"),
            "reason": "step 0 vision check passed" if ok else "step 0 vision check did not pass: no caption (D5)"}


m = meter.Meter()
ledger = meter.Ledger(amconf.STATE / "token_ledger.json", amconf.TOKEN_BUDGET)
lc = meter.LitellmCounter(meter=m, ledger=ledger)
lc.install()
out: dict = {"store": "DEMO", "user_id": USER, "search_call": SEARCH_KW}
rc = 0
RUN.transcript("## Step 6: image memory on DEMO (four synthetic bills with our descriptions, one LLM caption)")
try:
    try:
        out["frozen_inputs_match"] = frozen_ok()
        if not all(out["frozen_inputs_match"].values()):
            raise StepStop(f"frozen inputs differ from FREEZE.sha256: {out['frozen_inputs_match']}")
        with register_event_listeners([m]):
            pool = amconf.make_pool("AGENTMEM", 1, 4)
            client = cap_client = None
            try:
                emb = amconf.make_embedder(pool)
                client, info = stores.open_store(pool, hero_seed.STORE_ID, policy=SchemaPolicy.REQUIRE_EXISTING,
                                                 embedder=emb, llm=None, strategy=SearchStrategy.VECTOR,
                                                 extraction_config=MemoryExtractionConfig(extract_memories=False))
                out["demo_open"] = info
                out["hero_before"] = hero_state(pool)
                existing = [im.id for im in client.list_images(user_id=USER, limit=None)]
                out["images_before"] = existing
                foreign = sorted(set(existing) - set(ALL_IDS))
                if foreign:
                    raise StepStop(f"DEMO holds images of {USER} that are not this step's: {foreign}; nothing changed")
                prior_rows = [d for d in documents(pool) if d["record_id"] == CAPTION_ID]
                prior = [d for d in prior_rows if d["description"]]
                out["prior_caption"] = ({"description": prior[0]["description"],
                                         "created_at_utc": prior[0]["created_at_utc"]} if prior else None)
                out["prior_caption_row_without_text"] = bool(prior_rows) and not prior
                out["deleted_own_leftovers"] = {i: client.delete_image(i) for i in existing}
                # 2. the four images with our descriptions (no LLM attached to this client)
                added = []
                for im in SPEC["images"]:
                    data = (FROZEN / im["file"]).read_bytes()
                    rid = client.add_image(data, description=im["description"], image_id=im["image_id"], user_id=USER)
                    added.append({"image_id": im["image_id"], "returned": rid, "bytes": len(data),
                                  "sha256": hashlib.sha256(data).hexdigest()})
                    RUN.transcript(f"- add_image {im['image_id']} ({len(data)} bytes, our description) -> {rid}")
                out["added"] = added
                out["llm_calls_after_described_images"] = m.summary()["llm_calls"]
                # 3. read-back and search
                docs = documents(pool)
                out["documents_after_add"] = docs
                exp_mime = {im["image_id"]: im["mime_type"] for im in SPEC["images"]}
                out["mime_detected_as_frozen"] = {d["record_id"]: (exp_mime.get(d["record_id"]) or "")
                                                  in (d["document_metadata"] or "") for d in docs}
                out["image_chunks"] = image_chunks(pool)
                gold = {q["qid"]: q["gold_image_id"] for q in SPEC["questions"]}
                out["search_ranks"] = ranks(client, gold)
                for r in out["search_ranks"]:
                    RUN.transcript(f"- {r['qid']} '{r['question']}': right image at rank {r['rank_gold']} "
                                   f"of {len(r['returned_ids'])}")
                # 4. list_images, without and with bytes
                lst = client.list_images(user_id=USER, include_bytes=False, limit=None)
                out["list_images_no_bytes"] = [{"id": im.id, "mime_type": str(im.mime_type),
                                                "bytes_loaded": im.bytes is not None,
                                                "description": im.content} for im in lst]
                one = client.list_images(image_id=CAPTION_SOURCE_ID, user_id=USER, include_bytes=True)
                src = (FROZEN / next(im["file"] for im in SPEC["images"] if im["image_id"] == CAPTION_SOURCE_ID))
                out["list_images_with_bytes"] = [{"id": im.id, "mime_type": str(im.mime_type),
                                                  "bytes": len(im.bytes) if im.bytes is not None else None,
                                                  "sha256_equals_file": (im.bytes is not None and
                                                                         hashlib.sha256(im.bytes).hexdigest()
                                                                         == hashlib.sha256(src.read_bytes()).hexdigest())}
                                                 for im in one]
                RUN.transcript(f"- list_images: {len(lst)} without bytes; with bytes for {CAPTION_SOURCE_ID}: "
                               f"{out['list_images_with_bytes']}")
                # 5. one LLM caption (D5), only after step 0's vision check passed
                gate = caption_allowed()
                out["caption_gate"] = gate
                cap: dict = {"source_image_id": CAPTION_SOURCE_ID, "caption_image_id": CAPTION_ID,
                             "our_description": next(im["description"] for im in SPEC["images"]
                                                     if im["image_id"] == CAPTION_SOURCE_ID)}
                if gate["allowed"] and out["prior_caption"]:
                    # an earlier attempt already got the caption: re-add its text as given, no LLM call
                    data = src.read_bytes()
                    rid = client.add_image(data, description=out["prior_caption"]["description"],
                                           image_id=CAPTION_ID, user_id=USER)
                    cap["attempts"] = [{"attempt": 0, "ok": True, "returned": rid,
                                        "reused_from_earlier_attempt": out["prior_caption"]["created_at_utc"]}]
                elif gate["allowed"] and out["prior_caption_row_without_text"]:
                    gate = {**gate, "allowed": False,
                            "reason": "an earlier attempt's caption row had no text; D5 allows one image to the LLM, "
                                      "so it is not sent again"}
                    out["caption_gate"] = gate
                elif gate["allowed"]:
                    llm = amconf.make_llm(supports_vision=True)
                    cap_client, _ = stores.open_store(pool, hero_seed.STORE_ID, policy=SchemaPolicy.REQUIRE_EXISTING,
                                                      embedder=amconf.make_embedder(pool), llm=llm,
                                                      strategy=SearchStrategy.VECTOR,
                                                      extraction_config=MemoryExtractionConfig(extract_memories=False))
                    data = src.read_bytes()
                    attempts = []
                    for n in range(1 + len(RETRY_WAITS)):
                        t = time.perf_counter()
                        try:
                            rid = cap_client.add_image(data, image_id=CAPTION_ID, user_id=USER)
                            attempts.append({"attempt": n + 1, "ok": True, "returned": rid,
                                             "seconds": round(time.perf_counter() - t, 2)})
                            break
                        except meter.BudgetExceeded:
                            raise                    # the D5 ceiling stops the step, it is never a "refusal"
                        except Exception as exc:     # reported verbatim; the step goes on (PLAN 6 row 6, 10.5)
                            attempts.append({"attempt": n + 1, "ok": False, "error_type": type(exc).__name__,
                                             "error": str(exc)[:1500], "seconds": round(time.perf_counter() - t, 2)})
                            if [im.id for im in client.list_images(image_id=CAPTION_ID, user_id=USER)]:
                                break                # a row exists after all: never insert twice
                            if n < len(RETRY_WAITS):
                                time.sleep(RETRY_WAITS[n])
                    cap["attempts"] = attempts
                if gate["allowed"]:
                    w = wait_caption(pool)
                    cap["wait"] = {k: w[k] for k in ("row", "embedded_chunks", "seconds_waited")}
                    row = [d for d in documents(pool) if d["record_id"] == CAPTION_ID]
                    cap["stored"] = bool(row)
                    cap["generated_description"] = row[0]["description"] if row else None
                    ms_ = m.summary()
                    cap["llm_calls_for_caption"] = ms_["llm_calls"] - out["llm_calls_after_described_images"]
                    cap["llm_failures"] = ms_["llm_failures"]
                    if row and row[0]["description"]:
                        cap["outcome"] = ("caption generated (by the earlier attempt, re-added as given)"
                                          if out["prior_caption"] else "caption generated")
                        if w["embedded_chunks"] == 0:
                            cap["outcome"] += f", but no embedded chunk within {CAPTION_WAIT_S} s"
                    elif not row or ms_["llm_failures"] > 0:
                        cap["outcome"] = "caption refused"
                    else:
                        cap["outcome"] = f"no caption within {CAPTION_WAIT_S} s"
                    RUN.transcript(f"- caption ({cap['outcome']}, {len(cap['attempts'])} attempt(s), add_image returned "
                                   f"in {cap['attempts'][-1].get('seconds')} s; after {cap['wait']['seconds_waited']} s "
                                   f"more: text {'present' if cap['generated_description'] else 'absent'}, "
                                   f"{cap['wait']['embedded_chunks']} embedded chunk(s)): {cap['generated_description']!r}")
                    failed = [a for a in cap["attempts"] if not a["ok"]]
                    if failed:
                        RUN.transcript(f"  failed attempt(s): {[(a['error_type'], a['error']) for a in failed]}")
                    RUN.transcript(f"  ours: {cap['our_description']!r}")
                    if row:
                        out["image_chunks_after_caption"] = image_chunks(pool)
                        out["search_ranks_after_caption"] = ranks(client, gold, extra_id=CAPTION_ID)
                        for r in out["search_ranks_after_caption"]:
                            RUN.transcript(f"- after caption {r['qid']}: right image rank {r['rank_gold']}, "
                                           f"captioned copy rank {r['rank_caption_copy']}")
                else:
                    cap["outcome"] = "not attempted: " + gate["reason"]
                out["caption"] = cap
                out["hero_after"] = hero_state(pool)
                out["hero_unchanged"] = out["hero_after"] == out["hero_before"]
                out["documents_final"] = [{k: d[k] for k in ("record_id", "document_type", "bytes", "status")}
                                          for d in documents(pool)]
                with pool.acquire() as conn:
                    out["unlisted_objects_now"] = stores.unlisted_now(conn)
            finally:
                for c in (cap_client, client):
                    if c is not None:
                        c.close()
                pool.close()
        if not out.get("hero_unchanged", False):
            raise StepStop("the hero memories or links changed during step 6")
    except StepStop as exc:
        out["stopped"] = str(exc)
        RUN.log.error("step 6 stopped: %s", exc)
        RUN.transcript(f"- STOPPED: {exc}")
        rc = 1
finally:
    tok, ncalls = meter.step_tokens(m, lc)
    ledger.commit("s6", tok, ncalls)

out["meter"] = m.summary()
out["litellm_counter"] = lc.summary()
out["ledger_total_after"] = ledger.total
RUN.write_json("results", "s6_image_memory.json", out)
RUN.finish({"exit": rc, "ranks": {r["qid"]: r["rank_gold"] for r in out.get("search_ranks", [])},
            "caption": out.get("caption", {}).get("outcome"), "llm_calls": out["meter"]["llm_calls"],
            "tokens": tok, "hero_unchanged": out.get("hero_unchanged"), "stopped": out.get("stopped"),
            "unlisted_objects": len(out.get("unlisted_objects_now", []))})
sys.exit(rc)
